function validate([nestedList]) {
  if (!Array.isArray(nestedList) || nestedList.length < 1 || nestedList.length > 50) return 'nestedList needs 1 to 50 elements.';
  let problem = null;
  let count = 0;
  const walk = (list, depth) => {
    for (const item of list) {
      if (problem) return;
      if (++count > 20000) problem = 'nestedList is too large.';
      else if (depth > 50) problem = 'Nothing may be more than 50 lists deep.';
      else if (Array.isArray(item)) walk(item, depth + 1);
      else if (!Number.isInteger(item) || item < -100 || item > 100) problem = 'Each integer is between -100 and 100.';
    }
  };
  walk(nestedList, 1);
  return problem;
}

