function adapt(input, solve, kit) {
  // LeetCode's NestedInteger: one integer, or a list of NestedInteger elements.
  class NestedInteger {
    constructor(value) {
      this.value = value === undefined ? null : value;
      this.list = value === undefined ? [] : null;
    }
    isInteger() { return this.list === null; }
    getInteger() { return this.list === null ? this.value : null; }
    setInteger(value) { this.value = value; this.list = null; }
    add(elem) { if (this.list === null) { this.list = []; this.value = null; } this.list.push(elem); }
    getList() { return this.list; }
  }
  globalThis.NestedInteger = NestedInteger;
  const wrap = (item) => {
    if (!Array.isArray(item)) return new NestedInteger(item);
    const nested = new NestedInteger();
    for (const child of item) nested.add(wrap(child));
    return nested;
  };
  const [values] = input;
  const answer = solve(values.map(wrap));
  if (!Number.isInteger(answer)) throw new Error('depthSum must return an integer.');
  return answer;
}

