function depthSum(nestedList) {
  // Level by level: every integer met on level d is counted d times.
  let level = nestedList;
  let depth = 1;
  let sum = 0;
  while (level.length > 0) {
    const next = [];
    for (const item of level) {
      if (item.isInteger()) for (let t = 0; t < depth; t++) sum += item.getInteger();
      else next.push(...item.getList());
    }
    level = next;
    depth++;
  }
  return sum;
}

