function generate(rand, size) {
  const large = size === 'large';
  // The app accepts at most 11 levels of nesting, so large inputs stop there.
  const maxDepth = large ? 11 : 1 + Math.floor(rand() * 5);
  const span = large || rand() < 0.5 ? 100 : 5;
  const value = () => Math.floor(rand() * (2 * span + 1)) - span;
  let budget = large ? 1500 : 30;
  // A list whose own elements sit at the given depth; now and then it is empty.
  const makeList = (depth) => {
    const length = rand() < 0.1 ? 0 : 1 + Math.floor(rand() * (large ? 4 : 3));
    const list = [];
    for (let i = 0; i < length && budget > 0; i++) {
      budget--;
      list.push(depth < maxDepth && rand() < 0.4 ? makeList(depth + 1) : value());
    }
    return list;
  };
  const top = large ? 50 : 1 + Math.floor(rand() * 5);
  const nestedList = [];
  for (let i = 0; i < top; i++) nestedList.push(maxDepth > 1 && rand() < 0.5 ? makeList(2) : value());
  if (large) {
    // One chain that reaches the deepest level the app accepts.
    let chain = [value()];
    for (let depth = maxDepth - 1; depth >= 2; depth--) chain = [value(), chain];
    nestedList[0] = chain;
  }
  return [nestedList];
}
